/**
 * Canvas Confetti Engine (Standalone, lightweight)
 */
(function(window){
  var canvas, ctx, particles = [], animationId = null;

  function initCanvas(){
    if(!canvas){
      canvas = document.createElement('canvas');
      canvas.id = 'confetti-canvas';
      canvas.style.position = 'fixed';
      canvas.style.top = '0';
      canvas.style.left = '0';
      canvas.style.width = '100vw';
      canvas.style.height = '100vh';
      canvas.style.pointerEvents = 'none';
      canvas.style.zIndex = '999999';
      document.body.appendChild(canvas);
      ctx = canvas.getContext('2d');
      resizeCanvas();
      window.addEventListener('resize', resizeCanvas);
    }
  }

  function resizeCanvas(){
    if(canvas){
      canvas.width = window.innerWidth * window.devicePixelRatio;
      canvas.height = window.innerHeight * window.devicePixelRatio;
      ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
    }
  }

  var COLORS = ['#F59E0B', '#EC4899', '#8B5CF6', '#3B82F6', '#10B981', '#06B6D4', '#F43F5E', '#EAB308'];

  function Particle(x, y){
    this.x = x;
    this.y = y;
    this.size = Math.random() * 9 + 5;
    this.color = COLORS[Math.floor(Math.random() * COLORS.length)];
    this.vx = (Math.random() - 0.5) * 16;
    this.vy = -(Math.random() * 12 + 8);
    this.gravity = 0.35;
    this.rotation = Math.random() * 360;
    this.rotationSpeed = (Math.random() - 0.5) * 12;
    this.opacity = 1;
    this.friction = 0.98;
    this.wobble = Math.random() * 10;
  }

  Particle.prototype.update = function(){
    this.vx *= this.friction;
    this.vy += this.gravity;
    this.x += this.vx;
    this.y += this.vy;
    this.rotation += this.rotationSpeed;
    this.opacity -= 0.007;
    this.wobble += 0.1;
  };

  Particle.prototype.draw = function(c){
    c.save();
    c.translate(this.x + Math.sin(this.wobble) * 2, this.y);
    c.rotate((this.rotation * Math.PI) / 180);
    c.globalAlpha = Math.max(0, this.opacity);
    c.fillStyle = this.color;
    c.fillRect(-this.size / 2, -this.size / 4, this.size, this.size / 2);
    c.restore();
  };

  function loop(){
    if(!ctx) return;
    ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
    for(var i = particles.length - 1; i >= 0; i--){
      var p = particles[i];
      p.update();
      p.draw(ctx);
      if(p.opacity <= 0 || p.y > window.innerHeight + 50){
        particles.splice(i, 1);
      }
    }
    if(particles.length > 0){
      animationId = requestAnimationFrame(loop);
    } else {
      cancelAnimationFrame(animationId);
      animationId = null;
    }
  }

  window.confetti = function(options){
    initCanvas();
    options = options || {};
    var count = options.particleCount || 120;
    var originX = (options.origin && options.origin.x !== undefined ? options.origin.x : 0.5) * window.innerWidth;
    var originY = (options.origin && options.origin.y !== undefined ? options.origin.y : 0.5) * window.innerHeight;

    for(var i = 0; i < count; i++){
      particles.push(new Particle(originX, originY));
    }

    if(!animationId){
      loop();
    }
  };

  window.confettiBurst = function(){
    window.confetti({ particleCount: 140, origin: { x: 0.2, y: 0.7 } });
    window.confetti({ particleCount: 140, origin: { x: 0.8, y: 0.7 } });
    setTimeout(function(){
      window.confetti({ particleCount: 200, origin: { x: 0.5, y: 0.4 } });
    }, 300);
  };
})(window);
